// Base and derived classes for a polymorphic factory.
class Investment { 
public: 
    virtual ~Investment() = default; 
    virtual void printType() const = 0; 
};
class Stock : public Investment { 
public: 
    void printType() const override { std::cout << "Stock\n"; } 
};
class Bond : public Investment { 
public: 
    void printType() const override { std::cout << "Bond\n"; } 
};

// Factory function returning a unique_ptr to the base class.
std::unique_ptr<Investment> makeInvestment(const std::string& type) {
    if (type == "stock") {
        return std::make_unique<Stock>();
    } else if (type == "bond") {
        return std::make_unique<Bond>();
    }
    return nullptr;
}

// Usage:
auto myInvestment = makeInvestment("stock"); // Ownership transferred to myInvestment
if (myInvestment) {
    myInvestment->printType();
} // myInvestment goes out of scope, Stock object is destroyed automatically.
